// A free-drawing response, used instead of a <textarea> for genuine drawing
// tasks (sketch a shape, trace a pattern, draw a diagram, plot a graph) —
// mouse, touch, and stylus all work via Pointer Events. Emitted by the prompt
// as `<canvas class="drawing-canvas" id="..." data-aria-id="...">` alongside an
// optional `<button data-clear-canvas="<canvas id>">`.
//
// Canvases are wired page-wide rather than per activity type. A drawing
// surface is just a response control: it turns up inside
// `activity_open_ended_answer` sections, but equally inside
// `activity_fill_in_the_blank`, `text_only`, `text_and_images`, and
// `boxed_text` ones. Wiring it from a single activity initializer left every
// canvas outside that one section type dead on the page.
//
// Two optional tool buttons let the prompt offer a shading mode alongside
// plain line drawing — useful for "shade the region representing..." tasks
// (Venn diagrams, geometric regions) where a crisp line isn't the point:
//   <button data-pencil-tool="<canvas id>">   — thin, opaque line (default)
//   <button data-shade-tool="<canvas id>">    — wide, translucent "pencil
//                                                shading" brush; overlapping
//                                                passes darken naturally,
//                                                like hand-shading a region
const CANVAS_SELECTOR = "canvas.drawing-canvas"

interface DrawingTool {
  lineWidth: number
  strokeStyle: string
  globalAlpha: number
}
const PENCIL_TOOL: DrawingTool = {
  lineWidth: 4,
  strokeStyle: "#1f2937",
  globalAlpha: 1,
}
const SHADE_TOOL: DrawingTool = {
  lineWidth: 22,
  strokeStyle: "#1f2937",
  globalAlpha: 0.22,
}

/** A live view of one wired canvas, for callers that need to know whether the
 * learner has drawn anything (e.g. to enable a Submit button). */
export interface CanvasHandle {
  hasDrawing: () => boolean
}

// Canvases wired on the current page. Consumers (activity initializers) look
// themselves up in here rather than wiring canvases a second time.
const wired = new Map<HTMLCanvasElement, CanvasHandle>()
const changeListeners = new Set<() => void>()

function notifyChange(): void {
  changeListeners.forEach((fn) => fn())
}

/** Subscribe to "the learner drew or cleared something" on any wired canvas.
 * Returns an unsubscribe function. */
export function onDrawingChange(listener: () => void): () => void {
  changeListeners.add(listener)
  return () => changeListeners.delete(listener)
}

/** The wired canvases inside `root`, for folding into an activity's own
 * answered/empty accounting. Empty when the section contains no canvas. */
export function getCanvasHandles(root: ParentNode): Map<HTMLCanvasElement, CanvasHandle> {
  const handles = new Map<HTMLCanvasElement, CanvasHandle>()
  for (const canvas of root.querySelectorAll<HTMLCanvasElement>(CANVAS_SELECTOR)) {
    const handle = wired.get(canvas)
    if (handle) handles.set(canvas, handle)
  }
  return handles
}

function canvasStorageKey(canvas: HTMLCanvasElement): string | null {
  const ariaId = canvas.getAttribute("data-aria-id")
  if (!ariaId) return null
  const activityId = location.pathname
    .substring(location.pathname.lastIndexOf("/") + 1)
    .split(".")[0]
  return `${activityId}_${ariaId}`
}

function canvasPoint(canvas: HTMLCanvasElement, event: PointerEvent) {
  const rect = canvas.getBoundingClientRect()
  return {
    x: ((event.clientX - rect.left) * canvas.width) / rect.width,
    y: ((event.clientY - rect.top) * canvas.height) / rect.height,
  }
}

function applyTool(context: CanvasRenderingContext2D, tool: DrawingTool): void {
  context.lineCap = "round"
  context.lineJoin = "round"
  context.lineWidth = tool.lineWidth
  context.strokeStyle = tool.strokeStyle
  context.globalAlpha = tool.globalAlpha
}

/**
 * Wires one drawing canvas: pointer-based freehand drawing (mouse, touch, and
 * stylus all fire the same `pointer*` events), a PNG data-URL saved to
 * `localStorage` so the drawing survives a reload, and an optional
 * `[data-clear-canvas]` button. Returns a cleanup function and a live
 * `hasDrawing()` getter.
 */
function setupDrawingCanvas(
  canvas: HTMLCanvasElement,
  onChange: () => void,
): { hasDrawing: () => boolean; cleanup: () => void } {
  const context = canvas.getContext("2d")
  let hasDrawing = false
  let drawing = false
  let strokeMade = false
  let tool: DrawingTool = PENCIL_TOOL

  if (context) applyTool(context, tool)

  const key = canvasStorageKey(canvas)
  const stored = key ? localStorage.getItem(key) : null
  if (stored && context) {
    hasDrawing = true
    const image = new Image()
    image.addEventListener("load", () => {
      context.drawImage(image, 0, 0, canvas.width, canvas.height)
    })
    image.src = stored
  }

  // A canvas laid out at zero width/height (hidden container, a collapsed
  // parent, an off-screen tab) would make canvasPoint() divide by zero, so
  // every stroke paints NaN coordinates — nothing visible — while still
  // marking the question answered and saving a blank PNG. Ignore those.
  const hasLayout = () => {
    const rect = canvas.getBoundingClientRect()
    return rect.width > 0 && rect.height > 0
  }

  const onPointerDown = (event: PointerEvent) => {
    if (!context || !hasLayout()) return
    event.preventDefault()
    drawing = true
    strokeMade = false
    canvas.setPointerCapture(event.pointerId)
    const point = canvasPoint(canvas, event)
    context.beginPath()
    context.moveTo(point.x, point.y)
  }

  const onPointerMove = (event: PointerEvent) => {
    if (!drawing || !context) return
    event.preventDefault()
    const point = canvasPoint(canvas, event)
    context.lineTo(point.x, point.y)
    context.stroke()
    strokeMade = true
  }

  const finishStroke = (event: PointerEvent) => {
    if (!drawing) return
    drawing = false
    if (canvas.hasPointerCapture(event.pointerId)) {
      canvas.releasePointerCapture(event.pointerId)
    }
    if (strokeMade) {
      hasDrawing = true
      if (key) localStorage.setItem(key, canvas.toDataURL("image/png"))
      onChange()
    }
  }

  canvas.addEventListener("pointerdown", onPointerDown)
  canvas.addEventListener("pointermove", onPointerMove)
  canvas.addEventListener("pointerup", finishStroke)
  canvas.addEventListener("pointercancel", finishStroke)
  if (!canvas.hasAttribute("tabindex")) canvas.setAttribute("tabindex", "0")
  // The prompt is asked to include `touch-none`, but a canvas emitted without
  // it would otherwise pan the page instead of drawing on a touch device.
  if (!canvas.style.touchAction) canvas.style.touchAction = "none"

  const clearButton = canvas.id
    ? document.querySelector<HTMLElement>(`[data-clear-canvas="${canvas.id}"]`)
    : null
  const onClear = () => {
    if (!context) return
    context.clearRect(0, 0, canvas.width, canvas.height)
    hasDrawing = false
    if (key) localStorage.removeItem(key)
    onChange()
    canvas.focus()
  }
  clearButton?.addEventListener("click", onClear)

  const pencilButton = canvas.id
    ? document.querySelector<HTMLElement>(`[data-pencil-tool="${canvas.id}"]`)
    : null
  const shadeButton = canvas.id
    ? document.querySelector<HTMLElement>(`[data-shade-tool="${canvas.id}"]`)
    : null
  const setTool = (next: DrawingTool, activeButton: HTMLElement | null) => {
    tool = next
    if (context) applyTool(context, tool)
    pencilButton?.setAttribute("aria-pressed", String(activeButton === pencilButton))
    shadeButton?.setAttribute("aria-pressed", String(activeButton === shadeButton))
  }
  const onPencilClick = () => setTool(PENCIL_TOOL, pencilButton)
  const onShadeClick = () => setTool(SHADE_TOOL, shadeButton)
  if (pencilButton || shadeButton) {
    // A tool-switching UI is present — reflect the default (pencil) state
    // immediately so the active button is visually distinguishable from load.
    setTool(PENCIL_TOOL, pencilButton)
  }
  pencilButton?.addEventListener("click", onPencilClick)
  shadeButton?.addEventListener("click", onShadeClick)

  return {
    hasDrawing: () => hasDrawing,
    cleanup: () => {
      canvas.removeEventListener("pointerdown", onPointerDown)
      canvas.removeEventListener("pointermove", onPointerMove)
      canvas.removeEventListener("pointerup", finishStroke)
      canvas.removeEventListener("pointercancel", finishStroke)
      clearButton?.removeEventListener("click", onClear)
      pencilButton?.removeEventListener("click", onPencilClick)
      shadeButton?.removeEventListener("click", onShadeClick)
    },
  }
}

/**
 * Wires every drawing canvas on the page, whatever section type it sits in.
 * Returns a cleanup function, or null when the page has no canvas.
 */
export function initializeDrawingCanvases(): (() => void) | null {
  const canvases = Array.from(document.querySelectorAll<HTMLCanvasElement>(CANVAS_SELECTOR))
  if (canvases.length === 0) return null

  const cleanups: Array<() => void> = []
  for (const canvas of canvases) {
    if (wired.has(canvas)) continue
    const { hasDrawing, cleanup } = setupDrawingCanvas(canvas, notifyChange)
    wired.set(canvas, { hasDrawing })
    cleanups.push(() => {
      cleanup()
      wired.delete(canvas)
    })
  }

  return () => cleanups.forEach((off) => off())
}
