/**
 * Swap a plain `<input type="text">` for an equivalent `<math-field>`,
 * carrying over the attributes and value that matter for the rest of the
 * FITB runtime (persistence, feedback, grading) to keep working unchanged.
 * Used by activity-fill-in-the-blank.ts to convert every standalone FITB/
 * table input up front. Deliberately NOT used for `<textarea>` — MathLive's
 * `<math-field>` turned out to be a single continuous expression, not a
 * multi-line editor (no working Enter-for-newline, no working resize), so a
 * textarea instead gets a plain-text calculator (see math-field.ts's own
 * header) and is never swapped to a math-field at all.
 */
const CARRIED_ATTRS = [
  "id",
  "class",
  "style",
  "aria-label",
  "aria-invalid",
  "data-aria-id",
  "data-activity-item",
  "tabindex",
  "placeholder",
]

export function upgradeToMathField(el: HTMLInputElement): Element {
  const field = document.createElement("math-field")
  for (const attr of CARRIED_ATTRS) {
    const value = el.getAttribute(attr)
    if (value !== null) field.setAttribute(attr, value)
  }
  field.setAttribute("math-virtual-keyboard-policy", "manual")
  if (el.value) (field as unknown as { value: string }).value = el.value
  el.replaceWith(field)
  return field
}
