/**
 * Choice-response linking — for activities where the learner picks ONE radio
 * option out of several, and each option has its own free-text response field
 * right beneath it (e.g. "choose one topic, then write your response to it").
 *
 * Only the chosen option's field should be editable; the others must be
 * disabled and cleared, so a learner can't leave stray text in a field for an
 * option they didn't pick.
 *
 * Activity HTML is emitted by `prompts/activity_multiple_choice.liquid` and
 * `packages/pipeline/src/package-web.ts` for this pattern:
 *   - <input type="radio" data-activity-item="item-N"> options sharing one
 *     `name`, each followed (within the same wrapping card) by its own
 *     <textarea data-activity-item="item-M"> or <input type="text">.
 *
 * This module only wires the enable/disable/clear behavior — the radios'
 * own mutual exclusivity is native browser behavior, and submit/validation
 * for the section (if any) is handled by whichever other initializer already
 * targets its section type.
 */
const RADIO_SELECTOR = 'input[type="radio"][data-activity-item]'
const FIELD_SELECTOR = 'textarea[data-activity-item], input[type="text"][data-activity-item]'
const MAX_ANCESTOR_HOPS = 6

type Field = HTMLTextAreaElement | HTMLInputElement

function findPairedField(radio: HTMLInputElement): Field | null {
  let ancestor: HTMLElement | null = radio.parentElement
  for (let hop = 0; hop < MAX_ANCESTOR_HOPS && ancestor; hop++, ancestor = ancestor.parentElement) {
    const field = ancestor.querySelector<Field>(FIELD_SELECTOR)
    if (field) return field
  }
  return null
}

interface Pair {
  radio: HTMLInputElement
  field: Field
}

function groupByName(radios: HTMLInputElement[]): Map<string, HTMLInputElement[]> {
  const groups = new Map<string, HTMLInputElement[]>()
  for (const radio of radios) {
    if (!radio.name) continue
    const list = groups.get(radio.name) ?? []
    list.push(radio)
    groups.set(radio.name, list)
  }
  return groups
}

export function initializeChoiceResponseLinking(): (() => void) | null {
  if (typeof document === "undefined") return null

  const radios = Array.from(document.querySelectorAll<HTMLInputElement>(RADIO_SELECTOR))
  if (radios.length === 0) return null

  const cleanups: Array<() => void> = []

  for (const groupRadios of groupByName(radios).values()) {
    const pairs: Pair[] = groupRadios
      .map((radio) => ({ radio, field: findPairedField(radio) }))
      .filter((p): p is Pair => p.field !== null)

    // Nothing to link unless at least two options each have their own field.
    if (pairs.length < 2) continue

    const applyState = () => {
      for (const { radio, field } of pairs) {
        if (radio.checked) {
          field.disabled = false
        } else {
          if (field.value !== "") field.value = ""
          field.disabled = true
        }
      }
    }

    for (const { radio } of pairs) {
      radio.addEventListener("change", applyState)
      cleanups.push(() => radio.removeEventListener("change", applyState))
    }

    applyState()
  }

  if (cleanups.length === 0) return null

  return () => {
    cleanups.forEach((off) => off())
  }
}
