/**
 * Page-wide wiring for fill-in-the-blank math answer boxes — mirrors
 * ./drawing-canvas.ts's pattern (wired once per page, independent of which
 * activity section contains the field, since a math answer control is just
 * another answer control like a canvas is).
 *
 * Two kinds of target, two different keyboards:
 *   - A `<math-field>` (every marker-hydrated blank and standalone FITB
 *     input — see activity-fill-in-the-blank.ts's header) gets the real
 *     calculator: tapping a key inserts live-rendered LaTeX via the field's
 *     own `insert()`/`executeCommand()` API.
 *   - A FITB/table `<textarea>` (a longer free-form answer, left as a
 *     textarea on purpose — see that file's upgradeStandaloneInputs) is
 *     NEVER upgraded to a math-field. Tried that first; MathLive's
 *     `<math-field>` turned out to be fundamentally a single continuous
 *     expression, not a multi-line editor — Enter is bound to "commit", not
 *     "new line" (confirmed: typing a/Enter/b/Enter/c round-trips as the
 *     LaTeX string "abc", the Enters leave no trace), and it auto-shrinks
 *     the font to keep arbitrarily long content on one row rather than
 *     wrapping. Multi-line math *is* possible in MathLive (a `displaylines`
 *     environment plus overriding the Enter keybinding to `addRowAfter`),
 *     but proved too fragile to drive reliably from outside the field once
 *     mixed with real typing/focus/selection state — not worth the
 *     complexity for what's fundamentally the wrong tool for "write several
 *     steps of reasoning, with a formula somewhere in the middle." So a
 *     textarea instead gets a plain-text keyboard: tapping "x²" inserts the
 *     literal characters "^2" at the cursor via `setRangeText`, same as if
 *     the learner had typed it by hand — no live rendering, but genuine
 *     multi-line editing, a working resize handle, and Enter behaves
 *     normally, because it never stops being a real `<textarea>`.
 *
 * This module:
 *   - Imports "mathlive" (registers the <math-field> custom element) —
 *     side-effect deferred to here so pages with no FITB activity never pay
 *     for it.
 *   - Sets `mathModeSpace` so a space typed directly into a math-field (not
 *     via the calculator) survives as a LaTeX thin-space command instead of
 *     being silently dropped — math mode otherwise ignores whitespace,
 *     which would corrupt any existing multi-word text answer (see
 *     ../lib/latex-normalize.ts's latexSpacingToPlain, which undoes this
 *     for grading).
 *   - Registers a calculator-style virtual keyboard layout for math-fields:
 *     a "calculator" quick-access layer (x², 1/x, √, ±, x!,
 *     sin/cos/tan/log/ln) up front, plus MathLive's own built-in scientific
 *     layers (symbols, alphabetic, greek).
 *   - Renders a single floating "Math Keyboard" button, fixed to the
 *     top-right of the viewport, for the whole page — not one per field.
 *     Clicking it focuses the last-focused eligible field (or the first one
 *     on the page) and shows/hides the right kind of keyboard panel for it,
 *     along with a one-line reminder that the physical keyboard is still
 *     there for plain text — the panel is an added input path, not a
 *     lockout.
 *
 * MathLive's virtual keyboard detects when it's running inside an iframe and
 * proxies show()/hide() to `window.top` via postMessage, expecting a host
 * page there also running MathLive (its intended cross-frame architecture,
 * for a page that legitimately shares one keyboard across several iframes).
 * ADT Studio's own Storyboard editor previews a page exactly that way — but
 * its top window never loads MathLive, so the proxied show() silently goes
 * nowhere and no panel ever appears. Real shipped books are never iframed
 * (this module's own `initializeMathFields` runs inside the page itself), so
 * this only bites the in-Studio preview. Rather than modifying a completely
 * unrelated app (apps/studio) just to host a keyboard receiver, this module
 * detects the iframe case and renders its own minimal panel for math-fields
 * too in that case, built from the same CALCULATOR_ROWS keycap data.
 */
import type { MathfieldElement } from "mathlive"
import { FITB_SELECTOR } from "./activity-fill-in-the-blank"

/**
 * One keycap list, three consumers: MathLive's own virtual keyboard layout
 * (top-level pages, math-fields), the LaTeX-inserting fallback panel
 * (math-fields inside an unhosted iframe), and the plain-text panel
 * (textareas, always). `latex` uses MathLive's placeholder tokens: `#@` is
 * "whatever's immediately before the cursor" (the same token its own
 * built-in numeric keyboard uses for x²) — a calculator-style postfix key:
 * type 4, press x², get 4², not "4x²" (a literal `x` would insert a second
 * variable next to what was typed instead of exponentiating it). `#0` is a
 * plain empty placeholder, used for prefix operations (√, sin, a fresh
 * fraction) where you press the key first and type the argument after.
 * `plain`/`cursorBack` are the textarea equivalent: `plain` is inserted
 * verbatim at the cursor; `cursorBack` (default 0) moves the cursor back
 * that many characters afterward, e.g. "sqrt()" with cursorBack 1 lands the
 * cursor between the parens.
 */
const CALCULATOR_ROWS: {
  latex: string
  label: string
  plain: string
  cursorBack?: number
}[][] = [
  [
    { latex: "#@^2", label: "x²", plain: "^2" },
    { latex: "#@^{#?}", label: "xʸ", plain: "^" },
    { latex: "\\sqrt{#0}", label: "√x", plain: "sqrt()", cursorBack: 1 },
    { latex: "\\frac{#@}{#?}", label: "a/b", plain: "/" },
    { latex: "\\frac{1}{#@}", label: "1/x", plain: "1/" },
  ],
  [
    { latex: "#@!", label: "x!", plain: "!" },
    { latex: "\\pm", label: "±", plain: "±" },
    { latex: "\\pi", label: "π", plain: "π" },
    { latex: "(#0)", label: "()", plain: "()", cursorBack: 1 },
    { latex: "|#0|", label: "|x|", plain: "||", cursorBack: 1 },
  ],
  [
    { latex: "\\sin(#0)", label: "sin", plain: "sin()", cursorBack: 1 },
    { latex: "\\cos(#0)", label: "cos", plain: "cos()", cursorBack: 1 },
    { latex: "\\tan(#0)", label: "tan", plain: "tan()", cursorBack: 1 },
    { latex: "\\log(#0)", label: "log", plain: "log()", cursorBack: 1 },
    { latex: "\\ln(#0)", label: "ln", plain: "ln()", cursorBack: 1 },
  ],
]

function isInUnhostedIframe(): boolean {
  try {
    return window.self !== window.top
  } catch {
    // Cross-origin access throws — definitely a different (and definitely
    // not ours) top window.
    return true
  }
}

const MATH_FIELD_SELECTOR = "math-field[data-activity-item]"
// FITB/table textareas only — not open-ended's, which are much more likely
// genuine long-form answers than a fill-in-the-blank's. FITB_SELECTOR is
// itself a comma-separated list ("section[...blank], section[...table]") —
// wrap it in :is() before appending a descendant, or the suffix silently
// binds to only the last branch instead of both.
const ELIGIBLE_TEXTAREA_SELECTOR = `:is(${FITB_SELECTOR}) textarea[data-activity-item]`
const FAB_ID = "math-keyboard-fab"
const HINT_ID = "math-keyboard-hint"
const PANEL_HEIGHT = 116

type EligibleField = MathfieldElement | HTMLTextAreaElement

let keyboardConfigured = false

function configureVirtualKeyboard(): void {
  if (keyboardConfigured) return
  // Not present in non-browser-complete environments (e.g. jsdom in tests) —
  // MathLive itself no-ops the custom element registration there too.
  if (!window.mathVirtualKeyboard) return
  keyboardConfigured = true

  // Left at its default, MathLive resolves its own math fonts relative to
  // wherever esbuild happened to bundle this module — inside a book page
  // that resolves to a nonsense path under the book's own asset directory
  // (a 404 storm, then a broken/font-less keyboard). Point it at the CDN
  // copy matching the installed npm version instead.
  if (window.MathfieldElement) {
    window.MathfieldElement.fontsDirectory =
      "https://cdn.jsdelivr.net/npm/mathlive@0.110.0/fonts"
  }

  const calculatorLayer = { id: "calculator", rows: CALCULATOR_ROWS }

  window.mathVirtualKeyboard.layouts = [
    { id: "calculator", label: "Calc", layers: [calculatorLayer] },
    "default",
    "symbols",
    "greek",
  ]
}

/** A typed space survives as `\:` instead of vanishing (math mode ignores
 * plain whitespace) — undone for grading by latexSpacingToPlain(). */
function configureFieldSpacing(field: MathfieldElement): void {
  ;(field as unknown as { mathModeSpace: string }).mathModeSpace = "\\:"
}

// Inline styles, not Tailwind classes: this button is injected by runtime JS
// into an already-rendered book page, whose CSS is compiled from that page's
// own static content — a class combo nothing else on a textbook page would
// ever use (a fixed, circular, z-raised button) never makes it into that
// stylesheet, so the class names alone resolve to nothing. Inline styles
// always apply regardless of what any page's CSS bundle happens to contain.
function createFab(): HTMLButtonElement {
  const button = document.createElement("button")
  button.id = FAB_ID
  button.type = "button"
  button.setAttribute("aria-label", "Math keyboard")
  button.style.cssText =
    "position:fixed;top:1rem;right:1rem;z-index:2147483647;display:flex;" +
    "align-items:center;justify-content:center;height:48px;width:48px;" +
    "border-radius:9999px;border:1px solid #d1d5db;background:#fff;" +
    "box-shadow:0 2px 8px rgba(0,0,0,0.15);font-size:1.5rem;cursor:pointer;"
  button.textContent = "🧮"
  document.body.appendChild(button)
  return button
}

/** One-line reminder shown above whichever keyboard panel is open: the
 * physical keyboard is still the normal way to answer in words, this panel
 * is only for math notation. */
function createHintBanner(): HTMLDivElement {
  const banner = document.createElement("div")
  banner.id = HINT_ID
  banner.hidden = true
  banner.style.cssText =
    "position:fixed;left:0;right:0;z-index:2147483647;text-align:center;" +
    "font-size:0.75rem;padding:4px 0;background:#1f2937;color:#fff;"
  banner.textContent =
    "Use your normal keyboard to type words · use this keyboard for math"
  document.body.appendChild(banner)
  return banner
}

function positionHintBanner(banner: HTMLDivElement, heightPx: number): void {
  banner.style.bottom = `${heightPx}px`
}

/** Shared button-grid builder for both the LaTeX fallback panel (math-fields
 * in an unhosted iframe) and the plain-text panel (textareas) — same
 * CALCULATOR_ROWS layout, different key read off each entry and different
 * insert mechanism, supplied by the caller. */
function createKeyboardPanel(
  id: string,
  onKeyLabel: (row: (typeof CALCULATOR_ROWS)[number][number]) => void,
  onBackspace: () => void,
): HTMLDivElement {
  const panel = document.createElement("div")
  panel.id = id
  panel.hidden = true
  panel.style.cssText =
    `position:fixed;left:0;right:0;bottom:0;z-index:2147483646;height:${PANEL_HEIGHT}px;` +
    "background:#e5e7eb;padding:8px;box-sizing:border-box;" +
    "display:flex;flex-direction:column;gap:6px;font-family:system-ui,sans-serif;"

  CALCULATOR_ROWS.forEach((row) => {
    const rowEl = document.createElement("div")
    rowEl.style.cssText = "display:flex;gap:6px;flex:1;"
    row.forEach((key) => {
      const button = document.createElement("button")
      button.type = "button"
      button.textContent = key.label
      button.style.cssText =
        "flex:1;border:1px solid #d1d5db;border-radius:6px;background:#fff;" +
        "font-size:1rem;cursor:pointer;"
      // mousedown, not click: preserves focus/selection on the target field
      // instead of stealing it away first.
      button.addEventListener("mousedown", (e) => {
        e.preventDefault()
        onKeyLabel(key)
      })
      rowEl.appendChild(button)
    })
    panel.appendChild(rowEl)
  })

  const utilRow = document.createElement("div")
  utilRow.style.cssText = "display:flex;gap:6px;flex:1;"
  const backspace = document.createElement("button")
  backspace.type = "button"
  backspace.textContent = "⌫"
  backspace.style.cssText =
    "flex:1;border:1px solid #d1d5db;border-radius:6px;background:#fff;" +
    "font-size:1rem;cursor:pointer;"
  backspace.addEventListener("mousedown", (e) => {
    e.preventDefault()
    onBackspace()
  })
  utilRow.appendChild(backspace)
  panel.appendChild(utilRow)

  document.body.appendChild(panel)
  return panel
}

/** Insert plain text at the cursor of a real <textarea> — no LaTeX, no
 * field-type swap, so multi-line editing, resize, and Enter all keep
 * working exactly like they always have. */
function insertPlainText(
  textarea: HTMLTextAreaElement,
  text: string,
  cursorBack = 0,
): void {
  const start = textarea.selectionStart ?? textarea.value.length
  const end = textarea.selectionEnd ?? textarea.value.length
  textarea.setRangeText(text, start, end, "end")
  if (cursorBack > 0) {
    const pos = start + text.length - cursorBack
    textarea.selectionStart = textarea.selectionEnd = pos
  }
  textarea.dispatchEvent(new Event("input", { bubbles: true }))
  textarea.focus()
}

function textareaBackspace(textarea: HTMLTextAreaElement): void {
  const start = textarea.selectionStart ?? 0
  const end = textarea.selectionEnd ?? 0
  if (start === end && start > 0) {
    textarea.setRangeText("", start - 1, start, "end")
  } else {
    textarea.setRangeText("", start, end, "end")
  }
  textarea.dispatchEvent(new Event("input", { bubbles: true }))
  textarea.focus()
}

export function initializeMathFields(): (() => void) | null {
  if (typeof document === "undefined") return null
  const mathFields = Array.from(
    document.querySelectorAll<MathfieldElement>(MATH_FIELD_SELECTOR),
  )
  const textareas = Array.from(
    document.querySelectorAll<HTMLTextAreaElement>(ELIGIBLE_TEXTAREA_SELECTOR),
  )
  const eligible: EligibleField[] = [...mathFields, ...textareas]
  if (eligible.length === 0) return null

  const useMathFallback = isInUnhostedIframe()

  // Loading MathLive registers window.mathVirtualKeyboard and the
  // <math-field> custom element as a side effect.
  void import("mathlive").then(() => {
    if (!useMathFallback) configureVirtualKeyboard()
    mathFields.forEach(configureFieldSpacing)
  })

  // Track whichever field the learner last focused so the single floating
  // button knows which one to target; defaults to the first on the page.
  let activeField: EligibleField = eligible[0]
  const onFocusIn = (event: FocusEvent) => {
    const target = event.target as HTMLElement | null
    if (target && eligible.includes(target as EligibleField)) {
      activeField = target as EligibleField
    }
  }
  document.addEventListener("focusin", onFocusIn)

  const fab = document.getElementById(FAB_ID) ?? createFab()
  const hintBanner =
    (document.getElementById(HINT_ID) as HTMLDivElement | null) ?? createHintBanner()

  let mathPanel: HTMLDivElement | null = null
  let textPanel: HTMLDivElement | null = null
  let onKeyboardToggle: (() => void) | null = null

  function hideAllPanels(): void {
    if (mathPanel) mathPanel.hidden = true
    if (textPanel) textPanel.hidden = true
    if (!useMathFallback) window.mathVirtualKeyboard?.hide()
    hintBanner.hidden = true
  }

  function showPanel(panel: HTMLDivElement): void {
    panel.hidden = false
    hintBanner.hidden = false
    positionHintBanner(hintBanner, PANEL_HEIGHT)
  }

  // "virtual-keyboard-toggle" fires as a plain Event with no detail, after
  // the state has already changed — check .visible directly rather than
  // trying to read a payload off the event (that's what
  // "before-virtual-keyboard-toggle" carries, a different event that fires
  // before the change). Only relevant on top-level pages — that's the only
  // case where the native panel is the one actually being toggled.
  if (!useMathFallback && window.mathVirtualKeyboard) {
    onKeyboardToggle = () => {
      const visible = window.mathVirtualKeyboard.visible
      hintBanner.hidden = !visible
      if (visible) positionHintBanner(hintBanner, window.mathVirtualKeyboard.boundingRect.height)
    }
    window.mathVirtualKeyboard.addEventListener("virtual-keyboard-toggle", onKeyboardToggle)
  }

  const onFabClick = () => {
    activeField.focus()

    if (activeField.tagName === "TEXTAREA") {
      const textarea = activeField as HTMLTextAreaElement
      const panel =
        textPanel ??
        (textPanel = createKeyboardPanel(
          "math-keyboard-text-panel",
          (key) => insertPlainText(textarea, key.plain, key.cursorBack),
          () => textareaBackspace(textarea),
        ))
      const willShow = panel.hidden
      hideAllPanels()
      if (willShow) showPanel(panel)
      return
    }

    const field = activeField as MathfieldElement
    if (useMathFallback) {
      const panel =
        mathPanel ??
        (mathPanel = createKeyboardPanel(
          "math-keyboard-fallback-panel",
          (key) => {
            field.insert(key.latex)
            field.focus()
          },
          () => {
            field.executeCommand("deleteBackward")
            field.focus()
          },
        ))
      const willShow = panel.hidden
      hideAllPanels()
      if (willShow) showPanel(panel)
    } else {
      if (textPanel) textPanel.hidden = true
      const kb = window.mathVirtualKeyboard
      if (kb.visible) kb.hide()
      else kb.show()
    }
  }
  fab.addEventListener("click", onFabClick)

  return () => {
    document.removeEventListener("focusin", onFocusIn)
    fab.removeEventListener("click", onFabClick)
    fab.remove()
    if (onKeyboardToggle) {
      window.mathVirtualKeyboard.removeEventListener("virtual-keyboard-toggle", onKeyboardToggle)
    }
    hintBanner.remove()
    mathPanel?.remove()
    textPanel?.remove()
  }
}
